# System overview

The whole system as built: L1 BMW principles and L2 market evidence (including a research agent for competitors and trends) → AI analysis into feature requests → the product manager's gate (keep, reject with a required reason, priority, wishlist) → three car profiles → each build saved as a generation → L3 social test, which runs only after profiles exist. The detailed screen-by-screen path is in [`07-pm-workflow.md`](07-pm-workflow.md); how a decision is audited is in [`08-decision-audit.md`](08-decision-audit.md).

```mermaid
flowchart TB
  %% Dixi: principles first, market evidence as the engine, the PM decides, every decision keeps who · when · why.
  %% Colours follow branding/tokens.css: grey = AI on its own, blue = AI proposes, red = human only.
  %% Layers: L1 deep blue (BMW principles), L2 BMW blue (market evidence), L3 light blue (social test, after profiles).

  subgraph SRC["① Inputs"]
    direction LR
    S1[("BMW data (local only)<br/>customer feedback · customer studies<br/>sales · option list")]
    S2[("Public web<br/>competitor features · market trends")]
    S4[/"Series managers<br/>fundamentals per series"/]
  end

  subgraph LAY["② Layers L1 + L2"]
    direction LR
    L1[("L1 · BMW principles<br/>per series · owner per principle")]
    RA["Research agent<br/>competitor features people like<br/>+ market trends, with sources"]
    L2[("L2 · Market evidence<br/>feature requests · studies · sales<br/>option list · market signals")]
  end

  subgraph AN["③ AI analysis (per market + series)"]
    direction TB
    CL["Cluster feedback into feature requests<br/>Exterior · Interior · Digital · Powertrain"]
    UR["Urgency<br/>how many customers ask, in this market"]
    LK["Link requests ↔ competitors / trends"]
  end

  subgraph GATE["④ PM gate"]
    direction LR
    KP{{"Keep"}}
    RJ{{"Reject<br/>reason required"}}
    PR{{"Priority<br/>drag to order"}}
    WL{{"Wishlist<br/>star a competitor feature or trend"}}
  end

  DM[("Decisions<br/>keep · reject · wish<br/>reason · by · at")]
  BU["⑤ Build 3 car profiles<br/>Fix the basics · Tech-forward · Comfort &amp; craft<br/>follow the PM's priority<br/>score = L1 (principles + priority) + L2 coverage"]
  GEN[("⑥ Generations<br/>profiles · decisions · priority<br/>saved per build")]
  PDF[["Profile page + PDF<br/>catalogue style · decision trail"]]
  L3["⑦ L3 · Social test<br/>which profile tracks better (simulated)<br/>weight: 7 Series 2% · 5 Series 8% · 1 Series 20%"]

  S1 --> L2
  S2 --> RA --> L2
  S4 --> L1
  L2 --> CL --> UR --> LK
  LK --> KP & RJ & PR & WL
  KP & RJ & WL -- "who · when · why" --> DM
  KP & PR & WL --> BU
  L1 --> BU
  DM -. "rejected requests stay out" .-> BU
  BU --> GEN --> PDF
  DM --> PDF
  GEN -- "after profiles exist" --> L3
  L3 -- "updates scores" --> GEN
  GEN -. "edit and rebuild: decisions + priority loaded" .-> GATE

  classDef auto fill:#eef1f6,stroke:#5b6676,color:#121722
  classDef propose fill:#e8f0fc,stroke:#1c69d4,color:#121722
  classDef human fill:#fdecea,stroke:#e22718,color:#121722,stroke-width:2px
  classDef l1 fill:#16588e,stroke:#16588e,color:#ffffff
  classDef l2 fill:#1c69d4,stroke:#1c69d4,color:#ffffff
  classDef l3 fill:#e5f3fe,stroke:#2f95e6,color:#121722
  classDef store fill:#ffffff,stroke:#16588e,color:#121722
  classDef src fill:#f7f9fc,stroke:#98a2b3,color:#121722

  class S1,S2 src
  class S4,KP,RJ,PR,WL human
  class CL,UR,LK auto
  class RA,BU propose
  class L1 l1
  class L2 l2
  class L3 l3
  class DM,GEN,PDF store
```
# Hackathon build plan

The hackathon build plan, prioritised by the judging criteria.

```mermaid
gantt
  title Dixi 30-hour build (Sat 10 Oct, 14:00 to Sun 11 Oct, ~20:00)
  dateFormat YYYY-MM-DD HH:mm
  axisFormat %a %H:%M
  section Foundation
  Repo + Entire + Supabase schema (layers, weights, decisions) :a1, 2026-10-10 14:00, 2h
  BMW data → evidence, market + model tagged (swappable loader) :a2, after a1, 2h
  section Core 1 · Scoring + weights
  Source-weight table + per-model profiles (1 vs 7 Series) :b1, after a2, 2h
  Principles store L1 + principle gate                     :b2, after b1, 2h
  Scoring engine + volume-weighted conflict rule           :b3, after b2, 2h
  section Core 2 · Human in the loop
  Gates G1–G4 + roles + approve / edit / postpone / reject :c1, 2026-10-10 22:00, 3h
  Requirement writer (SMART, ~90% drafted, Keep / Edit)    :c2, after c1, 2h
  section Core 3 · Trace + memory + gaps
  Lineage store + 7 Series lineage view                    :d1, 2026-10-11 03:00, 3h
  Decision memory (PM-editable, versioned)                 :d2, after d1, 2h
  Evidence-gap detector + "What we don't know" panel       :d3, after d2, 2h
  section Hand-off
  Codebeamer export (ReqIF / CSV)                          :e1, 2026-10-11 10:00, 2h
  Dashboard (8 views) wired to real pipeline output         :e2, 2026-10-11 10:00, 4h
  section Optional (last)
  One illustrative concept image, labelled AI concept      :f1, 2026-10-11 14:00, 1h
  section Pitch
  Demo script · rehearsal · backup video                   :g1, 2026-10-11 15:00, 5h
```
/* Data contract for the requirement pipeline (/dashboard/[market]/[series]).
 *
 * Two sources fill it:
 *  - web/data-local/pipeline.json: built from BMW's dataset by scripts/build-pipeline-data.py. Git-ignored, local only.
 *  - src/lib/pipeline/example.ts: example data with the same shape, used when the local file is missing (e.g. on Vercel).
 */
import type { MarketId } from "@/lib/markets";

export type SeriesId = "F70" | "G60" | "G70";
export type Category = "Exterior" | "Interior" | "Digital" | "Powertrain";
export const CATEGORIES: Category[] = ["Exterior", "Interior", "Digital", "Powertrain"];

/** Markets in the feedback data. "OTHER" = countries outside the four app markets (KR, AU, CA, ZA, …). */
export type DataMarket = MarketId | "OTHER";

export interface OptionItem {
  /** BMW option code, e.g. "337". */
  code: string;
  /** Name as printed in the option list (German). */
  name: string;
  /** Price in EUR incl. VAT; null when the list shows "–,–" (standard or included). */
  priceEur: number | null;
  /** Section heading in the option list. */
  group: string;
}

export interface FeatureRequest {
  id: string;
  series: SeriesId;
  /** Short, PM-friendly name, e.g. "Simpler iDrive menus". */
  title: string;
  category: Category;
  /** One sentence: what customers ask for. */
  summary: string;
  /** Unique feedback records behind this request. */
  mentions: number;
  /** Mentions per market (only markets with data). */
  byMarket: Partial<Record<DataMarket, number>>;
  /** How the mentions split by feedback type. */
  types: { wants: number; difficult: number; defect: number };
  /** Feedback channels behind it (anonymised source names from the dataset). */
  sources: { name: string; count: number }[];
  /** Up to 3 short customer quotes (local data only; empty in the example set). */
  quotes: string[];
  /** The BMW taxonomy topic(s) the cluster was built from, for traceability. */
  taxonomy: string[];
  /** Related options already on the price list today, if any. */
  relatedOptions: OptionItem[];
}

export interface SeriesData {
  id: SeriesId;
  /** "1 Series" etc. */
  name: string;
  /** Unique feedback records for this series, per market. */
  feedbackByMarket: Partial<Record<DataMarket, number>>;
  /** Clustered requests, sorted by mentions (desc). */
  requests: FeatureRequest[];
  /** What customers like most (for context on the profile pages). */
  strengths: { title: string; mentions: number }[];
  /** Customer-study scores per market (0–10 for CN/EU; US uses its own 1–7 scale and is converted ×10/7). */
  studies: { market: MarketId; attribute: string; score: number }[];
  /** Units per market and year (2030 is BMW's forecast). */
  sales: { market: MarketId | "ROW"; y2024: number | null; y2025: number | null; y2030: number | null }[];
  /** Option list (Germany, July 2026), trimmed to the useful items. */
  options: OptionItem[];
}

export interface PipelineData {
  /** "bmw" when built from the local dataset, "example" otherwise. */
  origin: "bmw" | "example";
  generatedAt: string;
  series: SeriesData[];
}

/** L2 market signal found by the research agent: a competitor feature people like, or a market trend. Public sources only. */
export interface MarketSignal {
  id: string;
  kind: "competitor" | "trend";
  series: SeriesId[];

