uv run --no-project python -I - <<'EOF'
import re, glob, os
vals = {}
for f in ['.env', 'backend/.env']:
    for line in open(f):
        m = re.match(r'\s*([A-Z0-9_]+)\s*=\s*(.+)$', line.strip())
        if m and len(m.group(2).strip().strip('"\'')) >= 16 and any(k in m.group(1) for k in ('KEY','SECRET','TOKEN')):
            vals[m.group(1)] = m.group(2).strip().strip('"\'')
files = glob.glob(os.path.expanduser('~/.claude/projects/-Volumes-PJ-peresjav-hackathons-ehl-final-minuch-2026/*.jsonl'))
pat = re.compile(r"sk-(proj-)?[A-Za-z0-9_-]{20,}|tvly-[A-Za-z0-9_-]{10,}|eyJ[A-Za-z0-9_-]{30,}\.[A-Za-z0-9_-]{20,}|sb_secret_[A-Za-z0-9_-]{10,}")
for f in sorted(files, key=os.path.getmtime)[-6:]:
    t = open(f, errors='ignore').read()
    leaked = [k for k, v in vals.items() if v in t]
    print(os.path.basename(f)[:13], f"{len(t)//1024} KB", 'exact key values:', leaked or 'none', '| key-shaped strings:', len(pat.findall(t)))
EOF

